    20	public final class App {
    21	    private static final ObjectMapper MAPPER = new ObjectMapper()
    22	            .registerModule(new JavaTimeModule())
    23	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    24	            .enable(JsonGenerator.Feature.WRITE_BIGDECIMAL_AS_PLAIN);
    25	
    26	    private static final Set<String> RATE_PLANS = Set.of("STANDARD", "NON_REFUNDABLE");
    27	
    28	    public static void main(String[] args) throws Exception {
    29	        Config cfg = Config.fromEnv(System.getenv());
    30	        Db db = Db.connect(cfg);
    31	        MessageService messages = new MessageService(new MessagePolicy(cfg.messages()), Clock.system(cfg.zone()));
    32	        Javalin app = create(db, messages);
