    36	    public static Javalin create(Db db, MessageService messages) {
    37	        ReservationService reservations = new ReservationService(db, messages);
    38	        ReportService reports = new ReportService(db);
    39	
    40	        Javalin app = Javalin.create(c -> {
    41	            c.jsonMapper(new JavalinJackson(MAPPER, false));
    42	            c.showJavalinBanner = false;
    43	        });
    44	
    45	        app.get("/rooms", ctx -> ctx.json(reservations.rooms()));
    46	        app.post("/reservations", ctx -> ctx.status(201).json(reservations.create(parseNew(ctx))));
    47	        app.get("/reservations/{id}", ctx -> ctx.json(reservations.get(id(ctx))));
    48	        app.post("/reservations/{id}/confirmation", ctx -> ctx.json(reservations.confirm(id(ctx))));
    49	        app.post("/reservations/{id}/cancellation", ctx -> ctx.json(reservations.cancel(id(ctx))));
    50	        app.post("/reservations/{id}/check-in", ctx -> ctx.json(reservations.checkIn(id(ctx))));
    51	        app.post("/reservations/{id}/check-out", ctx -> ctx.json(reservations.checkOut(id(ctx))));
    52	        app.get("/reservations/{id}/document", ctx -> ctx.json(reservations.document(id(ctx))));
    53	        app.get("/messages", ctx -> ctx.json(db.tx(messages::list)));
    54	        app.get("/reports/occupancy", ctx -> {
    55	            LocalDate date = parseDate(ctx.queryParam("date"), "date");
    56	            ctx.contentType("text/csv; charset=utf-8").result(reports.occupancy(date));
    57	        });
    58	        app.get("/reports/revenue", ctx -> {
    59	            String m = ctx.queryParam("month");
    60	            YearMonth month;
    61	            try {
    62	                if (m == null) throw new DateTimeParseException("", "", 0);
    63	                month = YearMonth.parse(m);
    64	            } catch (DateTimeParseException e) {
    65	                throw ApiException.invalid("month deve estar no formato 2027-07");
    66	            }
    67	            ctx.contentType("text/csv; charset=utf-8").result(reports.revenue(month));
    68	        });
    69	
    70	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status, e.code, e.getMessage()));
    71	        app.exception(Exception.class, (e, ctx) -> {
    72	            e.printStackTrace();
    73	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
    74	        });
    75	        return app;
    76	    }
    77	
    78	    private static void error(Context ctx, int status, String code, String message) {
    79	        ctx.status(status).json(Map.of("error", code, "message", message));
    80	    }
    81	
    82	    private static long id(Context ctx) {
    83	        try {
    84	            return Long.parseLong(ctx.pathParam("id"));
    85	        } catch (NumberFormatException e) {
    86	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva não existe");
    87	        }
    88	    }
    89	
    90	    private static LocalDate parseDate(String s, String field) {
    91	        try {
    92	            if (s == null) throw new DateTimeParseException("", "", 0);
    93	            return LocalDate.parse(s);
    94	        } catch (DateTimeParseException e) {
    95	            throw ApiException.invalid(field + " deve estar no formato 2027-07-10");
    96	        }
    97	    }
    98	
    99	    private static ReservationService.NewReservation parseNew(Context ctx) {
   100	        JsonNode body;
   101	        try {
   102	            body = MAPPER.readTree(ctx.body());
   103	        } catch (JsonProcessingException e) {
   104	            throw ApiException.invalid("Corpo não é um JSON válido");
   105	        }
   106	        if (body == null || !body.isObject()) throw ApiException.invalid("Corpo deve ser um objeto JSON");
   107	
   108	        JsonNode room = body.get("roomNumber");
   109	        if (room == null || !room.isIntegralNumber() || !room.canConvertToInt()) {
   110	            throw ApiException.invalid("roomNumber é obrigatório e deve ser inteiro");
   111	        }
   112	        JsonNode guests = body.get("guests");
   113	        if (guests == null || !guests.isIntegralNumber() || !guests.canConvertToInt()) {
   114	            throw ApiException.invalid("guests é obrigatório e deve ser inteiro");
   115	        }
   116	        String name = text(body, "guestName");
   117	        String email = text(body, "guestEmail");
   118	        String cpf = text(body, "guestCpf");
   119	        LocalDate in = parseDate(text(body, "checkIn"), "checkIn");
   120	        LocalDate out = parseDate(text(body, "checkOut"), "checkOut");
   121	        String plan = text(body, "ratePlan");
   122	        if (!RATE_PLANS.contains(plan)) throw ApiException.invalid("ratePlan deve ser STANDARD ou NON_REFUNDABLE");
   123	        if (!out.isAfter(in)) throw ApiException.invalid("checkOut deve ser depois de checkIn");
   124	        if (guests.asInt() < 1) throw ApiException.invalid("guests deve ser pelo menos 1");
   125	        return new ReservationService.NewReservation(room.asInt(), name, email, cpf, in, out, guests.asInt(), plan);
   126	    }
   127	
   128	    private static String text(JsonNode body, String field) {
   129	        JsonNode n = body.get(field);
   130	        if (n == null || !n.isTextual() || n.asText().isBlank()) {
   131	            throw ApiException.invalid(field + " é obrigatório");
   132	        }
   133	        return n.asText();
   134	    }
   135	}
