    15	        lines.add(r.title() + " nº " + r.reservationId());
    16	        lines.add("Hóspede: " + r.guestName() + " (CPF " + formatCpf(r.guestCpf()) + ")");
    17	        lines.add("Quarto: " + r.roomNumber() + " (" + r.roomType() + ")");
    18	        lines.add("Entrada: " + r.checkIn().format(BR_DATE) + " | Saída: " + r.checkOut().format(BR_DATE)
    19	                + " | " + r.nights() + (r.nights() == 1 ? " diária" : " diárias"));
    20	        lines.add("Diárias: " + Money.brl(r.subtotal()));
    21	        if (r.discount().signum() > 0) {
    22	            lines.add("Desconto: " + Money.brl(r.discount()));
    23	        }
    24	        lines.add("Total: " + Money.brl(r.total()));
    25	        return String.join("\n", lines);
    26	    }
