    36	    static String formatCpf(String cpf) {
    37	        if (cpf.matches("\\d{11}")) {
    38	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
    39	        }
    40	        return cpf;
    41	    }
    42	}
