     1	package br.com.marealta;
     2	
     3	import java.time.LocalTime;
     4	import java.util.ArrayList;
     5	import java.util.List;
     6	import java.util.function.ToIntFunction;
     7	
     8	/**
     9	 * Regras aplicadas a toda mensagem antes de sair. Cada regra opcional tem um escopo
    10	 * (sempre, só no modo de teste, só fora dele, ou desligada), definido por instalação.
    11	 *
    12	 * Ordem: regras de bloqueio -> cópia para o arquivo -> redirecionamento do modo de teste.
    13	 * O redirecionamento vale para tudo o que sai (inclusive a cópia), então nada chega a endereço real
    14	 * em modo de teste, qualquer que seja a combinação de regras configurada.
    15	 */
    16	public final class MessagePolicy {
    17	
    18	    public enum Scope {
    19	        OFF, ALWAYS, TEST_ONLY, LIVE_ONLY;
    20	
    21	        boolean applies(boolean testMode) {
    22	            return switch (this) {
    23	                case OFF -> false;
    24	                case ALWAYS -> true;
    25	                case TEST_ONLY -> testMode;
    26	                case LIVE_ONLY -> !testMode;
    27	            };
    28	        }
    29	    }
    30	
    31	    public record Config(
    32	            boolean testMode,
    33	            String testAddress,
    34	            String archiveAddress,
    35	            Scope emailValidation,
    36	            Scope archiveCopy,
    37	            Scope quietHours,
    38	            LocalTime quietStart,
    39	            LocalTime quietEnd,
    40	            Scope dailyLimit,
    41	            int dailyLimitMax) {}
    42	
    43	    public record Draft(String to, String subject, String body) {}
    44	
    45	    /** Mensagem pronta: {@code originalTo} é o destinatário que seria o certo (para limite diário e auditoria). */
    46	    public record Out(String to, String subject, String body, boolean blocked, String originalTo, boolean copy) {}
    47	
    48	    private final Config cfg;
    49	
    50	    public MessagePolicy(Config cfg) {
    51	        this.cfg = cfg;
    52	    }
    53	
    54	    public static boolean isValidEmail(String a) {
    55	        if (a == null) return false;
    56	        int at = a.indexOf('@');
    57	        if (at <= 0 || at != a.lastIndexOf('@')) return false;
    58	        String domain = a.substring(at + 1);
    59	        return domain.contains(".") && !domain.startsWith(".") && !domain.endsWith(".");
    60	    }
    61	
    62	    /** @param sentToday quantas mensagens (não cópias) já foram enviadas hoje a esse endereço original */
    63	    public List<Out> process(Draft d, LocalTime now, ToIntFunction<String> sentToday) {
    64	        if (blocked(d, now, sentToday)) {
    65	            return List.of(new Out(d.to(), d.subject(), d.body(), true, d.to(), false));
    66	        }
    67	        List<Draft> drafts = new ArrayList<>();
    68	        List<Boolean> copies = new ArrayList<>();
    69	        drafts.add(d);
    70	        copies.add(false);
    71	        if (cfg.archiveCopy().applies(cfg.testMode())) {
    72	            drafts.add(new Draft(cfg.archiveAddress(), "[Cópia] " + d.subject(), d.body()));
    73	            copies.add(true);
    74	        }
    75	        List<Out> out = new ArrayList<>();
    76	        for (int i = 0; i < drafts.size(); i++) {
    77	            Draft x = drafts.get(i);
    78	            if (cfg.testMode()) {
    79	                out.add(new Out(cfg.testAddress(), "[TESTE] " + x.subject(),
    80	                        "Destinatário original: " + x.to() + "\n" + x.body(), false, x.to(), copies.get(i)));
    81	            } else {
    82	                out.add(new Out(x.to(), x.subject(), x.body(), false, x.to(), copies.get(i)));
    83	            }
    84	        }
    85	        return out;
    86	    }
    87	
    88	    private boolean blocked(Draft d, LocalTime now, ToIntFunction<String> sentToday) {
    89	        if (cfg.emailValidation().applies(cfg.testMode()) && !isValidEmail(d.to())) return true;
    90	        if (cfg.quietHours().applies(cfg.testMode()) && inQuietHours(now)) return true;
    91	        return cfg.dailyLimit().applies(cfg.testMode()) && sentToday.applyAsInt(d.to()) >= cfg.dailyLimitMax();
    92	    }
    93	
    94	    private boolean inQuietHours(LocalTime now) {
    95	        LocalTime s = cfg.quietStart(), e = cfg.quietEnd();
    96	        if (s.equals(e)) return false;
    97	        return s.isBefore(e) ? !now.isBefore(s) && now.isBefore(e) : !now.isBefore(s) || now.isBefore(e);
    98	    }
    99	}
