448	    64	        if (blocked(d, now, sentToday)) {
449	    65	            return List.of(new Out(d.to(), d.subject(), d.body(), true, d.to(), false));
450	    66	        }
451	    67	        List<Draft> drafts = new ArrayList<>();
452	    68	        List<Boolean> copies = new ArrayList<>();
453	    69	        drafts.add(d);
454	    70	        copies.add(false);
455	    71	        if (cfg.archiveCopy().applies(cfg.testMode())) {
456	    72	            drafts.add(new Draft(cfg.archiveAddress(), "[Cópia] " + d.subject(), d.body()));
457	    73	            copies.add(true);
458	    74	        }
459	    75	        List<Out> out = new ArrayList<>();
460	    76	        for (int i = 0; i < drafts.size(); i++) {
461	    77	            Draft x = drafts.get(i);
462	    78	            if (cfg.testMode()) {
463	    79	                out.add(new Out(cfg.testAddress(), "[TESTE] " + x.subject(),
