474	    90	        if (cfg.quietHours().applies(cfg.testMode()) && inQuietHours(now)) return true;
475	    91	        return cfg.dailyLimit().applies(cfg.testMode()) && sentToday.applyAsInt(d.to()) >= cfg.dailyLimitMax();
