    16	    public static Config fromEnv(Map<String, String> env) {
    17	        boolean test = "true".equalsIgnoreCase(env.getOrDefault("HOTEL_TEST_MODE", "").trim());
    18	        String[] quiet = env.getOrDefault("HOTEL_QUIET_HOURS", "22:00-07:00").split("-");
    19	        MessagePolicy.Config m = new MessagePolicy.Config(
    20	                test,
    21	                env.getOrDefault("HOTEL_TEST_ADDRESS", "testes@pousadamarealta.com.br"),
    22	                env.getOrDefault("HOTEL_ARCHIVE_ADDRESS", "arquivo@pousadamarealta.com.br"),
    23	                scope(env, "HOTEL_RULE_EMAIL_VALIDATION", MessagePolicy.Scope.ALWAYS),
    24	                scope(env, "HOTEL_RULE_ARCHIVE_COPY", MessagePolicy.Scope.LIVE_ONLY),
    25	                scope(env, "HOTEL_RULE_QUIET_HOURS", MessagePolicy.Scope.OFF),
    26	                LocalTime.parse(quiet[0].trim()),
    27	                LocalTime.parse(quiet[1].trim()),
    28	                scope(env, "HOTEL_RULE_DAILY_LIMIT", MessagePolicy.Scope.OFF),
    29	                Integer.parseInt(env.getOrDefault("HOTEL_DAILY_LIMIT", "3").trim()));
    30	        return new Config(
    31	                Integer.parseInt(env.getOrDefault("PORT", "7070").trim()),
    32	                env.get("DB_URL"),
    33	                env.get("DB_USER"),
    34	                env.get("DB_PASSWORD"),
    35	                ZoneId.of(env.getOrDefault("HOTEL_ZONE", "America/Sao_Paulo")),
    36	                m);
    37	    }
    38	
    39	    private static MessagePolicy.Scope scope(Map<String, String> env, String key, MessagePolicy.Scope def) {
    40	        String v = env.get(key);
    41	        return v == null || v.isBlank() ? def : MessagePolicy.Scope.valueOf(v.trim().toUpperCase());
    42	    }
    43	}
