     1	package br.com.marealta;
     2	
     3	import com.zaxxer.hikari.HikariConfig;
     4	import com.zaxxer.hikari.HikariDataSource;
     5	
     6	import java.sql.Connection;
     7	import java.sql.SQLException;
     8	import java.sql.Statement;
     9	import javax.sql.DataSource;
    10	
    11	public final class Db {
    12	    public interface TxFn<T> {
    13	        T apply(Connection c) throws SQLException;
    14	    }
    15	
    16	    private final DataSource ds;
    17	
    18	    public Db(DataSource ds) {
    19	        this.ds = ds;
    20	    }
    21	
    22	    public static Db connect(Config cfg) throws InterruptedException {
    23	        HikariConfig hc = new HikariConfig();
    24	        hc.setJdbcUrl(cfg.dbUrl());
    25	        hc.setUsername(cfg.dbUser());
    26	        hc.setPassword(cfg.dbPassword());
    27	        hc.setMaximumPoolSize(10);
    28	        hc.setInitializationFailTimeout(-1);
    29	        HikariDataSource ds = new HikariDataSource(hc);
    30	        Db db = new Db(ds);
    31	        // o banco pode ainda estar subindo: tenta por até ~60s
    32	        for (int i = 0; ; i++) {
    33	            try {
    34	                db.initSchema();
    35	                return db;
    36	            } catch (RuntimeException e) {
    37	                if (i >= 30) throw e;
    38	                Thread.sleep(2000);
    39	            }
    40	        }
    41	    }
    42	
    43	    public <T> T tx(TxFn<T> fn) {
    44	        try (Connection c = ds.getConnection()) {
    45	            c.setAutoCommit(false);
    46	            try {
