     9	import java.time.LocalTime;
    10	import java.time.ZonedDateTime;
    11	import java.util.ArrayList;
    12	import java.util.List;
    13	
    14	public final class MessageService {
    15	    public record Message(long id, String channel, String to, String subject, String body, String status) {}
    16	
    17	    private final MessagePolicy policy;
    18	    private final Clock clock;
    19	
    20	    public MessageService(MessagePolicy policy, Clock clock) {
    21	        this.policy = policy;
    22	        this.clock = clock;
    23	    }
    24	
    25	    /** Envia (ou bloqueia) uma mensagem dentro da transação da operação que a originou. */
    26	    public void send(Connection c, String to, String subject, String body) throws SQLException {
    27	        // o contador trava até o fim da transação: serializa envios, mantém a cópia colada na original
    28	        // e faz o limite diário contar certo
    29	        long nextId = nextId(c);
    30	        ZonedDateTime now = ZonedDateTime.now(clock);
    31	        LocalDate today = now.toLocalDate();
    32	        List<MessagePolicy.Out> outs = policy.process(
    33	                new MessagePolicy.Draft(to, subject, body),
    34	                now.toLocalTime(),
    35	                addr -> sentToday(c, addr, today));
    36	        for (int i = 0; i < outs.size(); i++) {
    37	            MessagePolicy.Out o = outs.get(i);
    38	            long id = i == 0 ? nextId : nextId(c);
    39	            try (PreparedStatement ps = c.prepareStatement(
    40	                    "INSERT INTO messages(id, channel, to_addr, subject, body, status, original_to, copy, sent_on) "
    41	                            + "VALUES (?,?,?,?,?,?,?,?,?)")) {
    42	                ps.setLong(1, id);
    43	                ps.setString(2, "EMAIL");
    44	                ps.setString(3, o.to());
    45	                ps.setString(4, o.subject());
    46	                ps.setString(5, o.body());
    47	                ps.setString(6, o.blocked() ? "BLOCKED" : "SENT");
    48	                ps.setString(7, o.originalTo().toLowerCase());
    49	                ps.setBoolean(8, o.copy());
    50	                ps.setObject(9, today);
    51	                ps.executeUpdate();
    52	            }
    53	        }
    54	    }
    55	
    56	    public List<Message> list(Connection c) throws SQLException {
    57	        List<Message> out = new ArrayList<>();
    58	        try (PreparedStatement ps = c.prepareStatement(
    59	                "SELECT id, channel, to_addr, subject, body, status FROM messages ORDER BY id");
    60	             ResultSet rs = ps.executeQuery()) {
    61	            while (rs.next()) {
    62	                out.add(new Message(rs.getLong(1), rs.getString(2), rs.getString(3), rs.getString(4),
    63	                        rs.getString(5), rs.getString(6)));
    64	            }
    65	        }
    66	        return out;
    67	    }
    68	
    69	    static long nextId(Connection c) throws SQLException {
    70	        return Ids.next(c, "messages");
    71	    }
    72	
    73	    private int sentToday(Connection c, String addr, LocalDate today) {
    74	        try (PreparedStatement ps = c.prepareStatement(
    75	                "SELECT count(*) FROM messages WHERE original_to = ? AND sent_on = ? AND status = 'SENT' AND NOT copy")) {
    76	            ps.setString(1, addr.toLowerCase());
    77	            ps.setObject(2, today);
    78	            try (ResultSet rs = ps.executeQuery()) {
    79	                rs.next();
    80	                return rs.getInt(1);
    81	            }
    82	        } catch (SQLException e) {
    83	            throw new RuntimeException(e);
    84	        }
    85	    }
    86	}
