     6	public final class Pricing {
     7	    private static final BigDecimal HIGH_SEASON = new BigDecimal("1.20");
     8	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
     9	
    10	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
    11	
    12	    private Pricing() {}
    13	
    14	    /** 15/12 até o fim de fevereiro, e julho inteiro. */
    15	    public static boolean isHighSeason(LocalDate night) {
    16	        int m = night.getMonthValue();
    17	        return m == 1 || m == 2 || m == 7 || (m == 12 && night.getDayOfMonth() >= 15);
    18	    }
    19	
    20	    public static BigDecimal nightPrice(BigDecimal rate, LocalDate night) {
    21	        return Money.round(isHighSeason(night) ? rate.multiply(HIGH_SEASON) : rate);
    22	    }
    23	
    24	    public static Quote quote(BigDecimal rate, LocalDate checkIn, LocalDate checkOut, String ratePlan) {
    25	        BigDecimal subtotal = Money.ZERO;
    26	        int nights = 0;
    27	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
    28	            subtotal = Money.round(subtotal.add(nightPrice(rate, d)));
    29	            nights++;
    30	        }
    31	        BigDecimal discount = ratePlan.equals("NON_REFUNDABLE")
    32	                ? Money.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT))
    33	                : Money.ZERO;
    34	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    35	    }
    36	}
