    16	    private static final String COLS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
    17	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
    18	
    19	    private final Db db;
    20	    private final MessageService messages;
    21	
    22	    public ReservationService(Db db, MessageService messages) {
    23	        this.db = db;
    24	        this.messages = messages;
