    27	    public List<Room> rooms() {
    28	        return db.tx(c -> {
    29	            List<Room> out = new ArrayList<>();
    30	            try (PreparedStatement ps = c.prepareStatement(
    31	                    "SELECT number, type, capacity, nightly_rate FROM rooms ORDER BY number");
    32	                 ResultSet rs = ps.executeQuery()) {
    33	                while (rs.next()) out.add(room(rs));
    34	            }
    35	            return out;
    36	        });
