    39	    public Reservation create(NewReservation n) {
    40	        return db.tx(c -> {
    41	            Room room = findRoom(c, n.roomNumber(), false);
    42	            if (n.guests() > room.capacity()) {
    43	                throw new ApiException(422, "CAPACITY_EXCEEDED",
    44	                        "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    45	            }
    46	            findRoom(c, n.roomNumber(), true); // trava o quarto: duas reservas simultâneas não passam juntas
    47	            try (PreparedStatement ps = c.prepareStatement(
    48	                    "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    49	                            + "AND check_in < ? AND check_out > ? LIMIT 1")) {
    50	                ps.setInt(1, n.roomNumber());
    51	                ps.setObject(2, n.checkOut());
    52	                ps.setObject(3, n.checkIn());
    53	                try (ResultSet rs = ps.executeQuery()) {
    54	                    if (rs.next()) {
    55	                        throw new ApiException(409, "ROOM_UNAVAILABLE", "O quarto já está reservado em alguma das noites");
