    60	            long id = Ids.next(c, "reservations");
    61	            try (PreparedStatement ps = c.prepareStatement("INSERT INTO reservations(" + COLS
    62	                    + ") VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NULL)")) {
    63	                ps.setLong(1, id);
    64	                ps.setInt(2, n.roomNumber());
    65	                ps.setString(3, n.guestName());
    66	                ps.setString(4, n.guestEmail());
    67	                ps.setString(5, n.guestCpf());
    68	                ps.setObject(6, n.checkIn());
    69	                ps.setObject(7, n.checkOut());
    70	                ps.setInt(8, n.guests());
    71	                ps.setString(9, n.ratePlan());
    72	                ps.setInt(10, q.nights());
    73	                ps.setBigDecimal(11, q.subtotal());
    74	                ps.setBigDecimal(12, q.discount());
    75	                ps.setBigDecimal(13, q.total());
    76	                ps.setString(14, "PENDING");
    77	                ps.setBigDecimal(15, Money.ZERO);
    78	                ps.executeUpdate();
    79	            }
    80	            return load(c, id, false);
    81	        });
    82	    }
