    84	    public Reservation get(long id) {
    85	        return db.tx(c -> load(c, id, false));
    86	    }
    87	
    88	    public Reservation confirm(long id) {
    89	        return db.tx(c -> {
    90	            Reservation r = load(c, id, true);
    91	            requireStatus(r, "confirmar", "PENDING");
    92	            update(c, id, "CONFIRMED", r.total(), null);
    93	            Reservation confirmed = load(c, id, false);
    94	            Receipt receipt = Receipt.of(confirmed, findRoom(c, confirmed.roomNumber(), false));
    95	            messages.send(c, confirmed.guestEmail(), "Reserva confirmada - Pousada Maré Alta",
    96	                    Documents.confirmationBody(receipt));
    97	            return confirmed;
    98	        });
    99	    }
   100	
   101	    public Reservation cancel(long id) {
   102	        return db.tx(c -> {
   103	            Reservation r = load(c, id, true);
   104	            requireStatus(r, "cancelar", "PENDING", "CONFIRMED");
   105	            BigDecimal refund = r.ratePlan().equals("STANDARD") && r.status().equals("CONFIRMED")
   106	                    ? r.amountPaid() : Money.ZERO;
   107	            update(c, id, "CANCELLED", r.amountPaid(), refund);
   108	            return load(c, id, false);
   109	        });
   110	    }
   111	
   112	    public Reservation checkIn(long id) {
   113	        return db.tx(c -> {
   114	            Reservation r = load(c, id, true);
   115	            requireStatus(r, "fazer check-in de", "CONFIRMED");
   116	            update(c, id, "CHECKED_IN", r.amountPaid(), r.refund());
   117	            return load(c, id, false);
   118	        });
   119	    }
   120	
   121	    public Receipt checkOut(long id) {
   122	        return db.tx(c -> {
   123	            Reservation r = load(c, id, true);
   124	            requireStatus(r, "fazer check-out de", "CHECKED_IN");
   125	            update(c, id, "CHECKED_OUT", r.amountPaid(), r.refund());
   126	            return Receipt.of(load(c, id, false), findRoom(c, r.roomNumber(), false));
   127	        });
   128	    }
   129	
   130	    public Receipt document(long id) {
   131	        return db.tx(c -> {
   132	            Reservation r = load(c, id, false);
   133	            if (!r.isPaid()) {
   134	                throw ApiException.notAllowed("Só existe comprovante para reserva paga");
   135	            }
   136	            return Receipt.of(r, findRoom(c, r.roomNumber(), false));
   137	        });
   138	    }
   139	
   140	    private static void requireStatus(Reservation r, String action, String... allowed) {
   141	        for (String s : allowed) if (r.status().equals(s)) return;
   142	        throw ApiException.notAllowed("Não é possível " + action + " uma reserva com situação " + r.status());
   143	    }
   144	
   145	    private static void update(Connection c, long id, String status, BigDecimal paid, BigDecimal refund) throws SQLException {
   146	        try (PreparedStatement ps = c.prepareStatement(
   147	                "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
   148	            ps.setString(1, status);
   149	            ps.setBigDecimal(2, paid);
   150	            ps.setBigDecimal(3, refund);
   151	            ps.setLong(4, id);
   152	            ps.executeUpdate();
   153	        }
   154	    }
   155	
   156	    private static Room findRoom(Connection c, int number, boolean lock) throws SQLException {
   157	        try (PreparedStatement ps = c.prepareStatement(
   158	                "SELECT number, type, capacity, nightly_rate FROM rooms WHERE number = ?" + (lock ? " FOR UPDATE" : ""))) {
   159	            ps.setInt(1, number);
   160	            try (ResultSet rs = ps.executeQuery()) {
   161	                if (!rs.next()) throw new ApiException(404, "ROOM_NOT_FOUND", "Quarto " + number + " não existe");
   162	                return room(rs);
   163	            }
   164	        }
   165	    }
   166	
   167	    private static Room room(ResultSet rs) throws SQLException {
   168	        return new Room(rs.getInt(1), rs.getString(2), rs.getInt(3), rs.getBigDecimal(4));
   169	    }
   170	
   171	    private static Reservation load(Connection c, long id, boolean lock) throws SQLException {
   172	        try (PreparedStatement ps = c.prepareStatement(
   173	                "SELECT " + COLS + " FROM reservations WHERE id = ?" + (lock ? " FOR UPDATE" : ""))) {
   174	            ps.setLong(1, id);
   175	            try (ResultSet rs = ps.executeQuery()) {
   176	                if (!rs.next()) throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva " + id + " não existe");
   177	                return reservation(rs);
   178	            }
   179	        }
   180	    }
   181	
   182	    static Reservation reservation(ResultSet rs) throws SQLException {
   183	        return new Reservation(rs.getLong(1), rs.getInt(2), rs.getString(3), rs.getString(4), rs.getString(5),
   184	                rs.getObject(6, LocalDate.class), rs.getObject(7, LocalDate.class), rs.getInt(8), rs.getString(9),
   185	                rs.getInt(10), rs.getBigDecimal(11), rs.getBigDecimal(12), rs.getBigDecimal(13), rs.getString(14),
   186	                rs.getBigDecimal(15), rs.getBigDecimal(16));
   187	    }
