 10	
 11	class DomainTest {
 12	    private static final BigDecimal STANDARD = new BigDecimal("249.90");
 13	
 14	    @Test
 15	    void highSeasonQuote() {
 16	        var q = Pricing.quote(STANDARD, LocalDate.of(2027, 7, 10), LocalDate.of(2027, 7, 12), "STANDARD");
 17	        assertEquals(2, q.nights());
 18	        assertEquals(new BigDecimal("599.76"), q.total());
 19	    }
 20	
 21	    @Test
 22	    void seasonBoundaries() {
 23	        assertFalse(Pricing.isHighSeason(LocalDate.of(2027, 12, 14)));
 24	        assertTrue(Pricing.isHighSeason(LocalDate.of(2027, 12, 15)));
 25	        assertTrue(Pricing.isHighSeason(LocalDate.of(2028, 2, 29)));
 26	        assertFalse(Pricing.isHighSeason(LocalDate.of(2028, 3, 1)));
 27	        assertFalse(Pricing.isHighSeason(LocalDate.of(2027, 8, 1)));
 28	    }
