 30	    @Test
 31	    void nonRefundableDiscount() {
 32	        var q = Pricing.quote(new BigDecimal("389.90"), LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), "NON_REFUNDABLE");
 33	        assertEquals(new BigDecimal("779.80"), q.subtotal());
 34	        assertEquals(new BigDecimal("116.97"), q.discount());
 35	        assertEquals(new BigDecimal("662.83"), q.total());
 36	    }
