 38	    @Test
 39	    void receiptText() {
 40	        var r = new Receipt(Receipt.TITLE, 7, "Carla Dias", "111.222.333-44", 201, "DELUXE",
 41	                LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), 2,
 42	                new BigDecimal("779.80"), Money.ZERO, new BigDecimal("779.80"));
