 44	                Comprovante de reserva nº 7
 45	                Hóspede: Carla Dias (CPF 111.222.333-44)
 46	                Quarto: 201 (DELUXE)
 47	                Entrada: 10/03/2027 | Saída: 12/03/2027 | 2 diárias
 48	                Diárias: R$ 779,80
 49	                Total: R$ 779,80""", Documents.receiptText(r));
 50	        assertEquals("R$ 1.234,56", Money.brl(new BigDecimal("1234.56")));
 51	    }
 52	
 53	    @Test
 54	    void emailValidation() {
 55	        assertTrue(MessagePolicy.isValidEmail("ana@gmail.com"));
 56	        assertFalse(MessagePolicy.isValidEmail("ana@gmail"));
 57	        assertFalse(MessagePolicy.isValidEmail("ana.gmail.com"));
 58	        assertFalse(MessagePolicy.isValidEmail("@gmail.com"));
 59	        assertFalse(MessagePolicy.isValidEmail("a@@gmail.com"));
 60	        assertFalse(MessagePolicy.isValidEmail("a@gmail."));
 61	    }
 62	
 63	    private static MessagePolicy policy(boolean test, MessagePolicy.Scope archive) {
 64	        return new MessagePolicy(new MessagePolicy.Config(test, "testes@x.com.br", "arquivo@x.com.br",
 65	                MessagePolicy.Scope.ALWAYS, archive, MessagePolicy.Scope.OFF, LocalTime.of(22, 0), LocalTime.of(7, 0),
 66	                MessagePolicy.Scope.OFF, 3));
 67	    }
 68	
 69	    private static final MessagePolicy.Draft DRAFT = new MessagePolicy.Draft("ana@gmail.com", "Oi", "Texto");
 70	
 71	    @Test
 72	    void liveSendsWithArchiveCopy() {
 73	        var out = policy(false, MessagePolicy.Scope.LIVE_ONLY).process(DRAFT, LocalTime.NOON, a -> 0);
 74	        assertEquals(2, out.size());
 75	        assertEquals("ana@gmail.com", out.get(0).to());
 76	        assertEquals("arquivo@x.com.br", out.get(1).to());
 77	        assertEquals("[Cópia] Oi", out.get(1).subject());
 78	        assertEquals("Texto", out.get(1).body());
 79	    }
 80	
 81	    @Test
 82	    void testModeRedirectsWithoutCopy() {
 83	        var out = policy(true, MessagePolicy.Scope.LIVE_ONLY).process(DRAFT, LocalTime.NOON, a -> 0);
 84	        assertEquals(1, out.size());
 85	        assertEquals("testes@x.com.br", out.get(0).to());
 86	        assertEquals("[TESTE] Oi", out.get(0).subject());
 87	        assertEquals("Destinatário original: ana@gmail.com\nTexto", out.get(0).body());
 88	    }
 89	
 90	    @Test
 91	    void testModeNeverReachesRealAddressEvenWithCopyForced() {
 92	        var out = policy(true, MessagePolicy.Scope.ALWAYS).process(DRAFT, LocalTime.NOON, a -> 0);
 93	        assertTrue(out.stream().noneMatch(o -> o.blocked() || !o.to().equals("testes@x.com.br")));
 94	    }
 95	
 96	    @Test
 97	    void invalidAddressIsBlockedWithoutCopy() {
 98	        for (boolean test : List.of(false, true)) {
 99	            var out = policy(test, MessagePolicy.Scope.ALWAYS)
100	                    .process(new MessagePolicy.Draft("ana@gmail", "Oi", "T"), LocalTime.NOON, a -> 0);
101	            assertEquals(1, out.size());
102	            assertTrue(out.get(0).blocked());
103	            assertEquals("ana@gmail", out.get(0).to());
104	            assertEquals("Oi", out.get(0).subject());
105	        }
106	    }
107	
108	    @Test
109	    void quietHoursAndDailyLimit() {
110	        var p = new MessagePolicy(new MessagePolicy.Config(false, "t@x.com.br", "a@x.com.br",
111	                MessagePolicy.Scope.ALWAYS, MessagePolicy.Scope.OFF, MessagePolicy.Scope.LIVE_ONLY,
112	                LocalTime.of(22, 0), LocalTime.of(7, 0), MessagePolicy.Scope.ALWAYS, 2));
113	        assertTrue(p.process(DRAFT, LocalTime.of(3, 0), a -> 0).get(0).blocked());
114	        assertTrue(p.process(DRAFT, LocalTime.of(23, 0), a -> 0).get(0).blocked());
115	        assertFalse(p.process(DRAFT, LocalTime.of(7, 0), a -> 1).get(0).blocked());
116	        assertTrue(p.process(DRAFT, LocalTime.of(12, 0), a -> 2).get(0).blocked());
117	    }
118	}

